// A world clock: a dot map of the world lit where the sun is up right now,
// twilight along the terminator and night beyond it, the cities marked on
// it, and a card per city with its time, how far it is ahead or behind, and
// its weather. It draws on the minute.
import { timeText, secondsToNextMinute, two } from './time'
import { subsolarPoint, sunAltitudeFrom } from './sun'
import { LAND_COLUMNS, isLand } from './land'

// Map rows from 84N to 60S (the land worth a dot), 3 degrees each.
const FIRST_ROW = 2
const LAST_ROW = 49

// A land dot's color by the sun's altitude there.
const SHADES: [number, string][] = [
  [-12, '#25324f'],
  [-6, '#4a4a72'],
  [-2, '#9a6f84'],
  [1, '#d9976b'],
  [5, '#f0cb86'],
  [12, '#f6e2a8'],
]

function hex(value: number) {
  const text = Math.max(0, Math.min(255, Math.round(value))).toString(16)
  return text.length < 2 ? '0' + text : text
}

function mix(a: string, b: string, t: number) {
  const pa = parseInt(a.substring(1), 16)
  const pb = parseInt(b.substring(1), 16)
  return '#' + hex(((pa >> 16) & 255) * (1 - t) + ((pb >> 16) & 255) * t) +
    hex(((pa >> 8) & 255) * (1 - t) + ((pb >> 8) & 255) * t) + hex((pa & 255) * (1 - t) + (pb & 255) * t)
}

function shadeAt(altitude: number) {
  if (altitude <= SHADES[0][0]) return SHADES[0][1]
  for (let i = 1; i < SHADES.length; i++) {
    if (altitude <= SHADES[i][0]) {
      return mix(SHADES[i - 1][1], SHADES[i][1], (altitude - SHADES[i - 1][0]) / (SHADES[i][0] - SHADES[i - 1][0]))
    }
  }
  return SHADES[SHADES.length - 1][1]
}

function offsetText(seconds: number) {
  if (seconds === 0) return 'Same time'
  const sign = seconds > 0 ? '+' : '−'
  const minutes = Math.round(Math.abs(seconds) / 60)
  const h = Math.floor(minutes / 60)
  const m = minutes % 60
  return sign + h + (m ? ':' + two(m) : '') + 'h'
}

const Sun = ({ className }) => (
  <svg viewBox="0 0 24 24" className={className}>
    <circle cx={12} cy={12} r={5} fill="currentColor" />
    <path d="M12 1v3M12 20v3M1 12h3M20 12h3M4.2 4.2l2.1 2.1M17.7 17.7l2.1 2.1M4.2 19.8l2.1-2.1M17.7 6.3l2.1-2.1" stroke="currentColor" strokeWidth={2} strokeLinecap="round" />
  </svg>
)
const Moon = ({ className }) => (
  <svg viewBox="0 0 24 24" className={className}>
    <path d="M20 14.5A8.5 8.5 0 0 1 9.5 4a8.5 8.5 0 1 0 10.5 10.5z" fill="currentColor" />
  </svg>
)

export function get(app: FrameOSApp, context: FrameOSContext) {
  const W = context.imageWidth ?? app.frame.width
  const H = context.imageHeight ?? app.frame.height
  const cities = Array.isArray(app.config.cities) ? app.config.cities : []
  if (!cities.length) {
    throw new Error('No cities yet')
  }
  const twelve = app.config.clock === '12h'
  const nowDate = new Date()
  const now = nowDate.getTime()
  frameos.setNextSleep(secondsToNextMinute(nowDate))
  const homeOffset = -nowDate.getTimezoneOffset() * 60
  const homeDay = Math.floor((now + homeOffset * 1000) / 86400000)

  const portrait = H > W
  const pad = Math.round(Math.min(W, H) * 0.035)
  const gap = Math.round(pad * 0.5)
  // The cards first: a row of up to four (two on a tall screen), then the map
  // as big as the rest of the screen lets it be.
  const columns = portrait ? 2 : Math.min(cities.length, 4)
  const cardRows = Math.ceil(cities.length / columns)
  const cardH = Math.round(Math.min(H * (portrait ? 0.13 : 0.2), (H * (portrait ? 0.55 : 0.42)) / cardRows))
  const small = Math.max(10, Math.round(cardH * 0.17))
  const cardText = Math.round(Math.min(cardH * 0.42, ((W - pad * 2) / columns) * 0.2))
  const headerH = small * 1.4 + pad
  const rows = LAST_ROW - FIRST_ROW + 1
  const room = H - headerH - cardRows * cardH - (cardRows - 1) * gap - pad * 2
  const mapW = Math.round(Math.min(W - pad * 2, (room * LAND_COLUMNS) / rows))
  const cell = mapW / LAND_COLUMNS
  const mapH = Math.round(cell * rows)

  // The land as dots, one path a shade so the map stays a handful of elements.
  const subsolar = subsolarPoint(now)
  const byShade: Record<string, string[]> = {}
  // A big panel on an ESP32 has the least memory to spare: there a dot
  // stands for four cells (6 degrees), elsewhere for one (3 degrees).
  const block = app.frame.embedded && W * H > 1000000 ? 2 : 1
  const dot = cell * block
  const r = dot * 0.36
  for (let row = FIRST_ROW; row + block - 1 <= LAST_ROW; row += block) {
    const latitude = 90 - (row + block / 2) * 3
    const cy = (row - FIRST_ROW + block / 2) * cell
    for (let column = 0; column + block - 1 < LAND_COLUMNS; column += block) {
      let land = 0
      for (let dr = 0; dr < block; dr++) for (let dc = 0; dc < block; dc++) if (isLand(column + dc, row + dr)) land++
      if (land * 2 < block * block || land === 0) continue
      const longitude = -180 + (column + block / 2) * 3
      const altitude = sunAltitudeFrom(subsolar, latitude, longitude)
      const bucket = Math.round(Math.max(-12, Math.min(12, altitude)) / 2) * 2
      const key = String(bucket)
      const cx = (column + block / 2) * cell
      // A dot is a tiny round-capped stroke: far less to hold than a circle.
      ;(byShade[key] = byShade[key] || []).push(`M${cx.toFixed(1)} ${cy.toFixed(1)}h0.1`)
    }
  }
  const project = (latitude: number, longitude: number) => [
    ((longitude + 180) / 360) * mapW,
    ((90 - latitude) / 3 - FIRST_ROW) * cell,
  ]
  const [sunX, sunY] = project(subsolar.latitude, subsolar.longitude)
  const utc = new Date(now)

  const map = (
    <svg viewBox={`0 0 ${mapW} ${mapH}`} className={`w-[${mapW}px] h-[${mapH}px]`}>
      <radialGradient id="daylight" gradientUnits="userSpaceOnUse" cx={sunX} cy={sunY} r={mapW * 0.3}>
        <stop offset="0" stopColor="#3b5a8c" stopOpacity="0.55" />
        <stop offset="1" stopColor="#3b5a8c" stopOpacity="0" />
      </radialGradient>
      <rect width={mapW} height={mapH} fill="#0e1729" />
      <rect width={mapW} height={mapH} fill="url(#daylight)" />
      {Object.keys(byShade).map((key) => <path d={byShade[key].join('')} fill="none" stroke={shadeAt(Number(key))} strokeWidth={r * 2} strokeLinecap="round" />)}
      <circle cx={sunX} cy={sunY} r={cell * 2.4} fill="#ffd36b" opacity={0.25} />
      <circle cx={sunX} cy={sunY} r={cell * 1.3} fill="#ffe39b" />
      {cities.map((city) => {
        const [x, y] = project(city.latitude, city.longitude)
        return (
          <g>
            <circle cx={x} cy={y} r={cell * 1.25} fill="none" stroke="#ffffff" strokeWidth={cell * 0.35} />
            <circle cx={x} cy={y} r={cell * 0.45} fill="#ffffff" />
          </g>
        )
      })}
    </svg>
  )

  return (
    <div className="flex flex-col w-full h-full bg-[#0b1220] text-white font-[FiraGO]">
      <div className={`flex items-baseline justify-between px-[${pad}px] pt-[${Math.round(pad * 0.6)}px]`}>
        <span className={`font-bold uppercase text-[${small}px] text-[#8ea0bf]`}>World clock</span>
        <span className={`uppercase text-[${small}px] text-[#8ea0bf]`}>{`UTC ${two(utc.getUTCHours())}:${two(utc.getUTCMinutes())}`}</span>
      </div>
      <div className="flex flex-1 items-center justify-center min-h-0">{map}</div>
      <div className={`grid grid-cols-${columns} gap-[${gap}px] px-[${pad}px] pb-[${pad}px]`}>
        {cities.map((city) => {
          const local = new Date(now + city.offset * 1000)
          const day = Math.floor((now + city.offset * 1000) / 86400000) - homeDay
          const lit = sunAltitudeFrom(subsolar, city.latitude, city.longitude) > -0.8
          const temperature = city.temperature == null ? '' : `${Math.round(city.temperature)}°`
          return (
            <div className={`flex flex-col justify-center h-[${cardH}px] rounded-lg bg-[#131d31] border-t-[3px] ${lit ? 'border-[#f0cb86]' : 'border-[#6d7fb3]'} px-[${Math.round(small * 0.8)}px] overflow-hidden`}>
              <div className={`flex items-center justify-between text-[${small}px] text-[#a9b6cf] uppercase font-bold`}>
                <span className="truncate">{city.name}</span>
                {lit ? <Sun className={`w-[${small}px] h-[${small}px] text-[#f0cb86]`} /> : <Moon className={`w-[${small}px] h-[${small}px] text-[#9fb0de]`} />}
              </div>
              <div className={`font-bold text-[${cardText}px] leading-none mt-[2px]`}>
                {timeText(local.getUTCHours(), local.getUTCMinutes(), twelve)}
              </div>
              <div className={`flex justify-between text-[${small}px] text-[#8ea0bf] mt-[3px]`}>
                <span className="truncate">{offsetText(city.offset - homeOffset) + (day > 0 ? ' · Tomorrow' : day < 0 ? ' · Yesterday' : '')}</span>
                <span>{temperature}</span>
              </div>
            </div>
          )
        })}
      </div>
    </div>
  )
}

