// World times: for each city on its own line, where it is (Open-Meteo's
// geocoder, remembered), its UTC offset at this moment, daylight saving included,
// and its weather, all in one Open-Meteo request. No key needed.

const MAX_CITIES = 8

type City = { name: string; latitude: number; longitude: number }

function cityLines(text: string) {
  const raw = String(text || '')
  const lines = raw.indexOf('\n') >= 0 ? raw.split('\n') : raw.split(',')
  return lines.map((line) => line.trim()).filter((line) => line.length > 0).slice(0, MAX_CITIES)
}

// "Name = 12.3, 45.6" names a place by its coordinates.
function placeFor(line: string, known: Record<string, City>): City {
  const pinned = line.match(/^(.*?)\s*=\s*(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)\s*$/)
  if (pinned) {
    return { name: pinned[1] || 'Here', latitude: Number(pinned[2]), longitude: Number(pinned[3]) }
  }
  if (known[line]) {
    return known[line]
  }
  const answer = frameos.fetchJson(
    'https://geocoding-api.open-meteo.com/v1/search?count=1&format=json&name=' + encodeURIComponent(line),
  )
  const hit = answer && answer.results && answer.results[0]
  if (!hit) {
    throw new Error('City not found: ' + line)
  }
  const city = { name: hit.name || line, latitude: hit.latitude, longitude: hit.longitude }
  known[line] = city
  return city
}

export function get(app: FrameOSApp) {
  const lines = cityLines(app.config.cities)
  if (!lines.length) {
    throw new Error('Add a city')
  }
  const known: Record<string, City> = frameos.recall('cities') || {}
  const cities = lines.map((line) => placeFor(line, known))
  frameos.remember('cities', known)

  const fahrenheit = app.config.temperatureUnit === 'fahrenheit'
  const url =
    'https://api.open-meteo.com/v1/forecast?timezone=auto&current=temperature_2m,weather_code,is_day' +
    '&latitude=' + cities.map((c) => c.latitude).join(',') +
    '&longitude=' + cities.map((c) => c.longitude).join(',') +
    '&temperature_unit=' + (fahrenheit ? 'fahrenheit' : 'celsius')
  const answer = frameos.fetchJson(url)
  if (!answer || answer.error) {
    throw new Error(answer && answer.reason ? answer.reason : 'No answer from Open-Meteo')
  }
  // One place comes back as an object, several as a list.
  const rows = Array.isArray(answer) ? answer : [answer]
  return cities.map((city, i) => {
    const row = rows[i] || {}
    const now = row.current || {}
    return {
      name: city.name,
      latitude: city.latitude,
      longitude: city.longitude,
      offset: row.utc_offset_seconds ?? 0,
      zone: row.timezone_abbreviation || '',
      temperature: now.temperature_2m,
      code: now.weather_code,
      fahrenheit,
    }
  })
}
